		private static long CMDFUNC_IF_LEVEL(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
            var atkBpp = handle.GetAttackPokeParam();
            var defBpp = handle.GetDefensePokeParam();

            if (atkBpp == null || defBpp == null)
                return CELL_FALSE;

            var check = (AILevel)args[0];
            int atkLevel = atkBpp.GetValue(BTL_POKEPARAM.ValueID.BPP_LEVEL);
            int defLevel = defBpp.GetValue(BTL_POKEPARAM.ValueID.BPP_LEVEL);

            // 01ff0428: EQUAL, then ATTACK (0), anything else compares as DEFENCE.
            if (check == AILevel.LEVEL_EQUAL)
                return (atkLevel == defLevel) ? CELL_TRUE : CELL_FALSE;

            if (check == AILevel.LEVEL_ATTACK)
                return (atkLevel > defLevel) ? CELL_TRUE : CELL_FALSE;

            return (atkLevel < defLevel) ? CELL_TRUE : CELL_FALSE;
        }
